/* `@/lib/utils` from EvilCharts' source: conditional class names are flattened by `clsx` first, then handed to BoardUI's `cx`.
 *
 * Upstream is a shadcn project and `cn` is generated by `shadcn init`, not part of the registry entry. What is wired here is
 * BoardUI's extended `tailwind-merge`: it recognizes type-scale classes like `text-caption-1-regular` and will not drop them
 * as colors when they share a string with color classes. Path aliases live in `vite.config.ts`, `vitest.config.ts` and
 * `src/react/tsconfig.json`. */
import { clsx, type ClassValue } from 'clsx';

import { cx } from '@/utils/cx';

export function cn(...inputs: ClassValue[]): string {
  return cx(clsx(inputs));
}
